/**
 * SeatAvailability Controller
 *
 * Seat availability inquiry API controller.
 * Supports both Prime Booking (Offer-based) and Post-Booking (Order-based).
 *
 * Workflows:
 * - WF_PB_SEAT: AirShopping -> SeatAvailability -> OfferPrice -> OrderCreate
 * - WF_PB_SEAT_SERVICE: AirShopping -> SeatAvailability -> ServiceList -> OfferPrice -> OrderCreate
 * - WF_HELD_SEAT: OrderRetrieve -> SeatAvailability -> OrderChange
 * - WF_TKT_SEAT: OrderRetrieve -> SeatAvailability -> OrderQuote -> OrderChange
 *
 * CRITICAL:
 * - TransactionID is generated by FE, middleware only does pass-through!
 * - Response returns PolarHub raw data as-is (no transformation!)
 */

import {
  Controller,
  Post,
  Body,
  HttpCode,
  HttpStatus,
  Logger,
  Res,
} from '@nestjs/common';
import { Response } from 'express';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBody,
  ApiHeader,
} from '@nestjs/swagger';
import { PolarHubService } from '../polarhub.service';
import {
  SeatAvailabilityRequestDto,
  SenderDto,
} from '../dto/seat-availability.dto';

@ApiTags('seat-availability')
@Controller('polarhub/seat-availability')
export class SeatAvailabilityController {
  private readonly logger = new Logger(SeatAvailabilityController.name);

  constructor(private readonly polarHubService: PolarHubService) {}

  @Post()
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Get available seats for flights',
    description: `Retrieves seat availability information for a flight segment.

**Supported Workflows:**
- **WF_PB_SEAT**: Prime Booking with seat selection
- **WF_PB_SEAT_SERVICE**: Prime Booking with seat + service
- **WF_HELD_SEAT**: Post-Booking seat change (Hold status)
- **WF_TKT_SEAT**: Post-Booking seat change (Ticketed status)

**Usage:**
- Prime Booking: Use \`offer\` field with AirShopping response data
- Post-Booking: Use \`order\` field with OrderRetrieve response data

**IMPORTANT:**
- TransactionID must be provided by FE (pass-through principle)
- For Prime Booking: Reuse same TransactionID from AirShopping
- For Post-Booking: Use same TransactionID from OrderRetrieve`,
  })
  @ApiHeader({
    name: 'x-date',
    description: 'RFC1123 timestamp (optional - for HMAC auth pass-through)',
    required: false,
  })
  @ApiHeader({
    name: 'Digest',
    description: 'SHA-512 digest (optional - for HMAC auth pass-through)',
    required: false,
  })
  @ApiHeader({
    name: 'Authorization',
    description: 'HMAC authorization (optional - for HMAC auth pass-through)',
    required: false,
  })
  @ApiBody({ type: SeatAvailabilityRequestDto })
  @ApiResponse({
    status: 200,
    description: `Seat availability data returned successfully.

Response contains:
- \`ALaCarteOffer\`: Seat options with pricing
- \`DataLists\`: Reference data (segments, etc.)

Returns raw PolarHub API response without transformation.`,
  })
  @ApiResponse({
    status: 400,
    description: 'Invalid request - missing or invalid parameters',
  })
  @ApiResponse({
    status: 401,
    description: 'Authentication failed - HMAC signature invalid',
  })
  @ApiResponse({
    status: 500,
    description: 'Internal server error or PolarHub API error',
  })
  async getSeatAvailability(
    @Body() request: SeatAvailabilityRequestDto,
    @Res({ passthrough: true }) res: Response,
  ): Promise<unknown> {
    // Determine request mode
    const mode = this.determineRequestMode(request);

    // Request logging
    this.logger.log({
      message: 'SeatAvailability request received',
      transactionId: request.transactionId,
      mode,
      hasSender: !!request.sender,
      paxCount: request.paxList.length,
      offerId: request.offer?.offerId,
      orderId: request.order?.orderId,
      hasCriteria: !!request.criteria,
      hasResponseParameter: !!request.responseParameter,
    });

    // Transform Offer (Prime Booking)
    const offer = request.offer
      ? {
          responseId: request.offer.responseId,
          offerId: request.offer.offerId,
          owner: request.offer.owner,
          offerItems: request.offer.offerItems
            ? request.offer.offerItems.map((item) => ({
                offerItemId: item.offerItemId,
                paxRefId: item.paxRefId,
                ...(item.paxSegmentRefId && {
                  paxSegmentRefId: item.paxSegmentRefId,
                }),
              }))
            : [],
        }
      : undefined;

    // Transform Order (Post-Booking)
    const order = request.order
      ? {
          orderId: request.order.orderId,
          orderItems: request.order.orderItems
            ? request.order.orderItems.map((item) => ({
                orderItemId: item.orderItemId,
                paxRefId: item.paxRefId,
                paxSegmentRefId: item.paxSegmentRefId,
              }))
            : undefined,
        }
      : undefined;

    // Call service
    const result = await this.polarHubService.getSeatAvailability({
      transactionId: request.transactionId,
      sender: this.transformSender(request.sender),
      offer,
      order,
      paxList: request.paxList.map((pax) => ({
        paxId: pax.paxId,
        ptc: pax.ptc,
        birthDate: pax.birthDate,
        loyaltyProgramAccount: pax.loyaltyProgramAccount,
      })),
      // Criteria (full CriteriaType4)
      ...(request.criteria && { criteria: request.criteria }),
      // ResponseParameter
      ...(request.responseParameter && { responseParameter: request.responseParameter }),
    });

    // Set response header
    res.setHeader('X-Transaction-Id', result.transactionId);

    // Return raw response (no transformation!)
    return result.response;
  }

  /**
   * Determine request mode (for logging)
   */
  private determineRequestMode(request: SeatAvailabilityRequestDto): string {
    if (request.offer && request.order) {
      return 'INVALID_BOTH';
    }
    if (request.offer) {
      return 'PRIME_BOOKING';
    }
    if (request.order) {
      return 'POST_BOOKING';
    }
    return 'UNKNOWN';
  }

  /**
   * Sender transformation helper (camelCase -> service params)
   */
  private transformSender(sender?: SenderDto) {
    if (!sender) return undefined;
    return {
      travelAgency: {
        agencyId: sender.travelAgency.agencyId,
        siteCode: sender.travelAgency.siteCode,
        agencyName: sender.travelAgency.agencyName,
        contactInfoRefId: sender.travelAgency.contactInfoRefId,
      },
    };
  }
}